(307002, 22751, 7758, '<td valign="top">like the tones in this shot.... give the shot alot of "mood".... good luck, Todd.</td>', 'like the tones in this shot.... give the shot alot of "mood".... good luck, Todd.', '2003-05-26 10:44:30.000000', NULL, 1),
(307003, 22490, 7543, '<td valign="top">Nice focus/DOF, clean and simple, I like it - 7</td>', 'Nice focus/DOF, clean and simple, I like it - 7', '2003-05-26 10:45:08.000000', NULL, 1),
