(307020, 22703, 327, '<td valign="top">This is just wonderful. WWII-40''s Very good tones.</td>', 'This is just wonderful. WWII-40''s Very good tones.', '2003-05-26 11:14:23.000000', NULL, 1),
(307022, 22726, 327, '<td valign="top">Frantastic lighting..the tones are just wonderful also. Love the pose, and the composition.</td>', 'Frantastic lighting..the tones are just wonderful also. Love the pose, and the composition.', '2003-05-26 11:16:46.000000', NULL, 1),
(307024, 22488, 327, '<td valign="top">Painterly feel, just lovely, rich.</td>', 'Painterly feel, just lovely, rich.', '2003-05-26 11:19:54.000000', NULL, 1),
