(307835, 22049, 1202, '<td valign="top">Wonderful shapes,lines and texture.  I find it a little uninteresting, I guess I need something for comparison....person, sky, lizard.   7</td>', 'Wonderful shapes,lines and texture.  I find it a little uninteresting, I guess I need something for comparison....person, sky, lizard.   7', '2003-05-27 11:53:12.000000', NULL, 1),
(307843, 22146, 2195, '<td valign="top">Oh I love this shot, ahh if only it could have headed the other way. It is a shot of poetic porportions. I like it as a whole, blown aout sky, highly contrasted grass and luminecient mist. If the horse was in the other direction it would be a 10 so  have 9. Good luck!</td>', 'Oh I love this shot, ahh if only it could have headed the other way. It is a shot of poetic porportions. I like it as a whole, blown aout sky, highly contrasted grass and luminecient mist. If the horse was in the other direction it would be a 10 so  have 9. Good luck!', '2003-05-27 11:54:57.000000', NULL, 1),
(307850, 22308, 1202, '<td valign="top">A superb pose and composition.  I think the skin tones are quite a bit flat and somewhat washed out.  Her skin looks so perfect, but the exposure didn''t capture it as it could have.   Nice job.  8</td>', 'A superb pose and composition.  I think the skin tones are quite a bit flat and somewhat washed out.  Her skin looks so perfect, but the exposure didn''t capture it as it could have.   Nice job.  8', '2003-05-27 12:06:37.000000', NULL, 1),
