(310091, 22069, 4493, '<td valign="top">Very strong leading lines. Great capture. Good tones. 9 -danny</td>', 'Very strong leading lines. Great capture. Good tones. 9 -danny', '2003-05-29 14:03:32.000000', NULL, 1),
(310093, 22617, 4493, '<td valign="top">I can feel her competitive spirit! This is a real nice capture with good b/w work. 9 -danny</td>', 'I can feel her competitive spirit! This is a real nice capture with good b/w work. 9 -danny', '2003-05-29 14:04:17.000000', NULL, 1),
(310098, 22479, 7628, '<td valign="top">Beautiful gauzy layers of petals - very nice in B&amp;W.  I''m uncomfortable with the composition, the way the large flower is cropped on the right, and the flecks of light in the background are distracting.  I would try either cropping more of the large flower off which would emphasize the smaller one more, and bring the viewers eye to the great detail texture in the large flowers petals.  Or reshot and try to include the whole large flower - oerhaps in controller contitions with a solid background.</td>', 'Beautiful gauzy layers of petals - very nice in B&W.  I''m uncomfortable with the composition, the way the large flower is cropped on the right, and the flecks of light in the background are distracting.  I would try either cropping more of the large flower off which would emphasize the smaller one more, and bring the viewers eye to the great detail texture in the large flowers petals.  Or reshot and try to include the whole large flower - oerhaps in controller contitions with a solid background.', '2003-05-29 14:08:36.000000', NULL, 1),
(310156, 22680, 4055, '<td valign="top">One of my favourites this week. Good composition and the sepia tone is perfect. So is focus and the cropping. I don´t know how you could have done it better. Meets the challenge very well. Well done and good luck!</td>', 'One of my favourites this week. Good composition and the sepia tone is perfect. So is focus and the cropping. I don´t know how you could have done it better. Meets the challenge very well. Well done and good luck!', '2003-05-29 14:49:17.000000', NULL, 1),
