(310339, 22665, 5728, '<td valign="top">You''ve given this photo a real old fashioned feel, the sepia toning works very well - 9.</td>', 'You''ve given this photo a real old fashioned feel, the sepia toning works very well - 9.', '2003-05-29 16:45:51.000000', NULL, 1),
(310358, 22709, 5728, '<td valign="top">Ah Wingy right? Thought I recognise you there, again another supurb self portrait from you, good work.</td>', 'Ah Wingy right? Thought I recognise you there, again another supurb self portrait from you, good work.', '2003-05-29 16:54:12.000000', NULL, 1),
(310373, 22069, 5728, '<td valign="top">fabulous perspective, very well done</td>', 'fabulous perspective, very well done', '2003-05-29 17:00:29.000000', NULL, 1),
(310407, 22680, 714, '<td valign="top">Ok this shot bugs me.  hahahaha....excellent shot. Great focus.  Good luck</td>', 'Ok this shot bugs me.  hahahaha....excellent shot. Great focus.  Good luck', '2003-05-29 18:03:06.000000', NULL, 1),
(310409, 22637, 714, '<td valign="top">Great shot.  Unique and interesting.  Good luck!</td>', 'Great shot.  Unique and interesting.  Good luck!', '2003-05-29 18:04:49.000000', NULL, 1),
(310419, 22049, 5266, '<td valign="top">The lines and shadows in this photo are incredible, but I think a different "duotone" would have had more impact - maybe a sepia?  The b&amp;w is a bit blah.  Great subject, great composition.</td>', 'The lines and shadows in this photo are incredible, but I think a different "duotone" would have had more impact - maybe a sepia?  The b&w is a bit blah.  Great subject, great composition.', '2003-05-29 18:40:28.000000', NULL, 1),
(310422, 22463, 5266, '<td valign="top">The dog looks very guilty!!!  Love the expressions - great subject - thanks for something different.</td>', 'The dog looks very guilty!!!  Love the expressions - great subject - thanks for something different.', '2003-05-29 18:48:41.000000', NULL, 1),
(310429, 22767, 7485, '<td valign="top">Great composition, but the image looks a little pixelated and oversharpened</td>', 'Great composition, but the image looks a little pixelated and oversharpened', '2003-05-29 19:03:39.000000', NULL, 1),
(310438, 22362, 6505, '<td valign="top">This really cracked me up!  I must be sick! 8</td>', 'This really cracked me up!  I must be sick! 8', '2003-05-29 19:17:49.000000', NULL, 1),
(310442, 22194, 6505, '<td valign="top">Excellent clarity!  Beautiful shot. Lighting and focus are perfect.  Great job!</td>', 'Excellent clarity!  Beautiful shot. Lighting and focus are perfect.  Great job!', '2003-05-29 19:22:47.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(310478, 22215, 2333, '<td valign="top">Nice composition, I like the abatract nature of the shot. Is the slight blurring to bottom right due to jet exhaust? I''ve experinced this on some of my aerial shots.</td>', 'Nice composition, I like the abatract nature of the shot. Is the slight blurring to bottom right due to jet exhaust? I''ve experinced this on some of my aerial shots.', '2003-05-29 20:07:40.000000', NULL, 1),
(310480, 22117, 2333, '<td valign="top">I like your choice of framing, perspective provides nice effect. Very nice exposure; captured both the natural and artificial lighting elements.</td>', 'I like your choice of framing, perspective provides nice effect. Very nice exposure; captured both the natural and artificial lighting elements.', '2003-05-29 20:11:01.000000', NULL, 1),
(310481, 22491, 2333, '<td valign="top">Good work... The gentle sweeping cirrus clouds add a nice element. What IR filter did you use?</td>', 'Good work... The gentle sweeping cirrus clouds add a nice element. What IR filter did you use?', '2003-05-29 20:13:31.000000', NULL, 1),
(310482, 22405, 2333, '<td valign="top">I love the mood of this photo; very nice work. Simple, emotive, the grain adds that extra something...</td>', 'I love the mood of this photo; very nice work. Simple, emotive, the grain adds that extra something...', '2003-05-29 20:16:10.000000', NULL, 1),
(310492, 22726, 7504, '<td valign="top">I like the softness of this, it looks like a shot from the 60''s or something.  Nice work, and lovely model.</td>', 'I like the softness of this, it looks like a shot from the 60''s or something.  Nice work, and lovely model.', '2003-05-29 21:12:52.000000', NULL, 1),
(310493, 22632, 7504, '<td valign="top">She''s lovely, and I really like her name.  A little too soft focus for my taste, but I can see what you were trying to accomplish.</td>', 'She''s lovely, and I really like her name.  A little too soft focus for my taste, but I can see what you were trying to accomplish.', '2003-05-29 21:14:03.000000', NULL, 1),
(310497, 22755, 7504, '<td valign="top">Very sweet.  I hope people aren''t voting you down cause it''s a kid pic.  Nice mood, and good choice of color.</td>', 'Very sweet.  I hope people aren''t voting you down cause it''s a kid pic.  Nice mood, and good choice of color.', '2003-05-29 21:17:38.000000', NULL, 1),
(310503, 22627, 6597, '<td valign="top">like the effect of the clouds</td>', 'like the effect of the clouds', '2003-05-29 21:46:07.000000', NULL, 1),
(310504, 22729, 6597, '<td valign="top">good arrangment 9</td>', 'good arrangment 9', '2003-05-29 21:47:22.000000', NULL, 1),
(310506, 22781, 6597, '<td valign="top">rain drops gives this wow power thanks   9</td>', 'rain drops gives this wow power thanks   9', '2003-05-29 21:50:18.000000', NULL, 1),
(310508, 22273, 8130, '<td valign="top">Great, looks like he just stepped out of a John Steinbeck novel.  I don''t normally care for "people pix", but this one just pulled me in and didn''t let go.</td>', 'Great, looks like he just stepped out of a John Steinbeck novel.  I don''t normally care for "people pix", but this one just pulled me in and didn''t let go.', '2003-05-29 22:10:17.000000', NULL, 1),
(310510, 22767, 1717, '<td valign="top">very cool shot!  i love the tones and the lighting is great.  well done!</td>', 'very cool shot!  i love the tones and the lighting is great.  well done!', '2003-05-29 22:28:43.000000', NULL, 1),
(310511, 22768, 6900, '<td valign="top">The tones of this duotone are amazing.  There is a lot of stuff going on - especially with the back ''row'' - but other than the cut off basket on the right, none of it seems out of place.  The upper right is a bit darker than the rest, but this is a superb shot.  10 and good luck!</td>', 'The tones of this duotone are amazing.  There is a lot of stuff going on - especially with the back ''row'' - but other than the cut off basket on the right, none of it seems out of place.  The upper right is a bit darker than the rest, but this is a superb shot.  10 and good luck!', '2003-05-29 22:32:03.000000', NULL, 1),
(310516, 22780, 1143, '<td valign="top">This shot works well in duotone. I actually think you could adjust the black level a tad to give even more contrast with more darkness in the shadows. I personally don''t have a lot of emotional interest in the shot. Technically it''s quite good, but without something more... it''s more of a stock shot than something to hang on the wall obviously. I do really like how the light is spreading out though.</td>', 'This shot works well in duotone. I actually think you could adjust the black level a tad to give even more contrast with more darkness in the shadows. I personally don''t have a lot of emotional interest in the shot. Technically it''s quite good, but without something more... it''s more of a stock shot than something to hang on the wall obviously. I do really like how the light is spreading out though.', '2003-05-29 22:48:11.000000', NULL, 1),
(310520, 22214, 3540, '<td valign="top">I originally gave this a 5, but going back thru my stuff, I am moving it up some.   I really like the way this looks like a vintage photo, but somewhat clearer.  I think the thing that really gives it some character is the tree on the left leaning into the center of the frame.  Nice work with this one and best of luck</td>', 'I originally gave this a 5, but going back thru my stuff, I am moving it up some.   I really like the way this looks like a vintage photo, but somewhat clearer.  I think the thing that really gives it some character is the tree on the left leaning into the center of the frame.  Nice work with this one and best of luck', '2003-05-29 22:54:07.000000', NULL, 1),
(310526, 22751, 6325, '<td valign="top">The tone adds an old time feel to the image - good choice.</td>', 'The tone adds an old time feel to the image - good choice.', '2003-05-29 23:03:02.000000', NULL, 1),
(310528, 22283, 6325, '<td valign="top">This has a good depth to the image. The rose seems to stand out.</td>', 'This has a good depth to the image. The rose seems to stand out.', '2003-05-29 23:05:06.000000', NULL, 1),
(310532, 22199, 554, '<td valign="top">super  lighting....too soft focus for my taste...8</td>', 'super  lighting....too soft focus for my taste...8', '2003-05-29 23:10:04.000000', NULL, 1),
(310533, 22792, 6325, '<td valign="top">Exceptional composition. Thought provoking.</td>', 'Exceptional composition. Thought provoking.', '2003-05-29 23:12:05.000000', NULL, 1),
(310538, 22617, 6325, '<td valign="top">Good motion shot. The tones work well.</td>', 'Good motion shot. The tones work well.', '2003-05-29 23:18:18.000000', NULL, 1),
(310570, 22267, 5351, '<td valign="top">Awesome shot - absolutely love the angle this was taken at.  The only thing I can think of to improve it would be that the lighting may be a little strong.  Very interesting subject - very good cropping/composition and tone.  High score:)</td>', 'Awesome shot - absolutely love the angle this was taken at.  The only thing I can think of to improve it would be that the lighting may be a little strong.  Very interesting subject - very good cropping/composition and tone.  High score:)', '2003-05-29 23:34:16.000000', NULL, 1),
(310572, 22724, 6325, '<td valign="top">The tones in the container are very good. I think the container could have stood on its own. The composition including the flower seems too busy.</td>', 'The tones in the container are very good. I think the container could have stood on its own. The composition including the flower seems too busy.', '2003-05-29 23:35:03.000000', NULL, 1),
(310575, 22199, 5351, '<td valign="top">Very interesting lighting effect and I like the softness to this photo:)</td>', 'Very interesting lighting effect and I like the softness to this photo:)', '2003-05-29 23:35:53.000000', NULL, 1),
(310591, 22471, 5351, '<td valign="top">This is an interesting composition.  Unfortunately, I feel the harsh light on the bottom center is far too distracting.   A tighter crop may help this. I really like from the clock upwards and like the tone as well:).</td>', 'This is an interesting composition.  Unfortunately, I feel the harsh light on the bottom center is far too distracting.   A tighter crop may help this. I really like from the clock upwards and like the tone as well:).', '2003-05-29 23:41:06.000000', NULL, 1),
(310606, 22658, 5351, '<td valign="top">This is a absolutely terrific shot.  This should do extremely well in the challenge!  The use of an everyday object to make it look like a piece of art is a very special talent that I feel this truly demonstrates.  Not only did you meet the challenge well, but I feel  the composition, tones and border selection are outstanding.   Good Luck in the challenge - 10!</td>', 'This is a absolutely terrific shot.  This should do extremely well in the challenge!  The use of an everyday object to make it look like a piece of art is a very special talent that I feel this truly demonstrates.  Not only did you meet the challenge well, but I feel  the composition, tones and border selection are outstanding.   Good Luck in the challenge - 10!', '2003-05-29 23:47:24.000000', NULL, 1),
(310607, 22787, 6325, '<td valign="top">Wonderful shot and use of duotones. Getting that bright lighitng at the base of the falls was a good find.</td>', 'Wonderful shot and use of duotones. Getting that bright lighitng at the base of the falls was a good find.', '2003-05-29 23:48:33.000000', NULL, 1),
(310608, 22787, 5351, '<td valign="top">Very pretty place that you captured very well!</td>', 'Very pretty place that you captured very well!', '2003-05-29 23:48:41.000000', NULL, 1),
(310614, 22069, 6325, '<td valign="top">Wonferful form. It would have stood on its own, the bird is a bonus to break up the structured portion.</td>', 'Wonferful form. It would have stood on its own, the bird is a bonus to break up the structured portion.', '2003-05-29 23:53:05.000000', NULL, 1),
(310615, 22458, 6325, '<td valign="top">Didn''t your mother tell you not to sit so close to the TV? Very good image and use of duotones. And fun as a bonus.</td>', 'Didn''t your mother tell you not to sit so close to the TV? Very good image and use of duotones. And fun as a bonus.', '2003-05-29 23:55:29.000000', NULL, 1),
(310617, 22768, 5351, '<td valign="top">I am a big fan of baskets (living in rural New England helps) and have several color prints of them on my wall.  I really love this photo with one exception - I like the composition of everything except the shoes - I find they draw my attention when I would rather focus on the baskets.  Just my opinion, but I could definately see this as a salable print with that one change. Hope this helps and good luck in the challenge! (good score)</td>', 'I am a big fan of baskets (living in rural New England helps) and have several color prints of them on my wall.  I really love this photo with one exception - I like the composition of everything except the shoes - I find they draw my attention when I would rather focus on the baskets.  Just my opinion, but I could definately see this as a salable print with that one change. Hope this helps and good luck in the challenge! (good score)', '2003-05-29 23:56:58.000000', NULL, 1),
(310618, 22791, 6325, '<td valign="top">I bet you had this shot for Sound as well. Good shot and use of duotone.</td>', 'I bet you had this shot for Sound as well. Good shot and use of duotone.', '2003-05-30 00:00:52.000000', NULL, 1),
(310622, 22054, 6325, '<td valign="top">I like the image and composition. A pure black and white might have been a better choice of tones.</td>', 'I like the image and composition. A pure black and white might have been a better choice of tones.', '2003-05-30 00:09:37.000000', NULL, 1),
(310623, 22199, 6325, '<td valign="top">The bright white creates a dramatic image - good chice.</td>', 'The bright white creates a dramatic image - good chice.', '2003-05-30 00:10:41.000000', NULL, 1),
(310624, 22308, 2344, '<td valign="top">This would be an absolutely lovely portrait if it weren''t for the focus.  It is absolutely critical IMO for the eyes in a portrait to be sharp and unfortunately they are not.  The auto focus was probably tricked into focusing on the hat.</td>', 'This would be an absolutely lovely portrait if it weren''t for the focus.  It is absolutely critical IMO for the eyes in a portrait to be sharp and unfortunately they are not.  The auto focus was probably tricked into focusing on the hat.', '2003-05-30 00:12:06.000000', NULL, 1),
(310625, 22633, 2344, '<td valign="top">I''m not sure which means you used to get to a duotone but this doesn''t look like I would have expected it to.  The deep brown in the sky is very nice but the brown is either absent or barely there in the architecture.  The lighter midtones hold almost no colour at all while the darker ones on the right side of the picture have fairly saturated browns.  I will be interested to see exactly how you did this.</td>', 'I''m not sure which means you used to get to a duotone but this doesn''t look like I would have expected it to.  The deep brown in the sky is very nice but the brown is either absent or barely there in the architecture.  The lighter midtones hold almost no colour at all while the darker ones on the right side of the picture have fairly saturated browns.  I will be interested to see exactly how you did this.', '2003-05-30 00:15:05.000000', NULL, 1),
(310627, 22732, 2344, '<td valign="top">This is a cool concept. I would have executed it differently though. I think the dof is slightly too shallow. The only point of sharp focus is the knob on the bottom third of the picture.  That cord sticking out is hugely distracting as well.  I like that you''ve included the guitarist in the image even though I would have photographed him playing rather than looking at the camera. (just a personal preference)  All in all I like this shot</td>', 'This is a cool concept. I would have executed it differently though. I think the dof is slightly too shallow. The only point of sharp focus is the knob on the bottom third of the picture.  That cord sticking out is hugely distracting as well.  I like that you''ve included the guitarist in the image even though I would have photographed him playing rather than looking at the camera. (just a personal preference)  All in all I like this shot', '2003-05-30 00:18:20.000000', NULL, 1),
(310629, 22049, 5351, '<td valign="top">I really like the contrast and textures in this - great shot!</td>', 'I really like the contrast and textures in this - great shot!', '2003-05-30 00:19:25.000000', NULL, 1),
(310630, 22730, 5351, '<td valign="top">Cool shot - nice tones and border selection.</td>', 'Cool shot - nice tones and border selection.', '2003-05-30 00:20:34.000000', NULL, 1),
(310631, 22488, 5351, '<td valign="top">Love the almost surreal look to this - good job!</td>', 'Love the almost surreal look to this - good job!', '2003-05-30 00:21:23.000000', NULL, 1),
(310632, 22462, 6325, '<td valign="top">Great tone for a nautical theme.</td>', 'Great tone for a nautical theme.', '2003-05-30 00:27:47.000000', NULL, 1),
(310633, 22785, 6104, '<td valign="top">awesome photo</td>', 'awesome photo', '2003-05-30 00:29:08.000000', NULL, 1),
(310634, 22069, 6104, '<td valign="top">nice shot, I like the bird :D</td>', 'nice shot, I like the bird :D', '2003-05-30 00:31:20.000000', NULL, 1),
(310635, 22458, 6104, '<td valign="top">that is totaly creepy, I love it.</td>', 'that is totaly creepy, I love it.', '2003-05-30 00:31:59.000000', NULL, 1),
(310636, 22057, 6325, '<td valign="top">Good street scene. The tones work well.</td>', 'Good street scene. The tones work well.', '2003-05-30 00:35:33.000000', NULL, 1),
(310637, 22054, 6104, '<td valign="top">that totaly reminds me of "The Ring,"  except in a none creepy kind of way. great work.</td>', 'that totaly reminds me of "The Ring,"  except in a none creepy kind of way. great work.', '2003-05-30 00:36:17.000000', NULL, 1),
(310641, 22273, 6325, '<td valign="top">Fantastic in all respects.</td>', 'Fantastic in all respects.', '2003-05-30 00:42:00.000000', NULL, 1),
(310643, 22685, 6325, '<td valign="top">What a great image and use of duotones.</td>', 'What a great image and use of duotones.', '2003-05-30 00:46:07.000000', NULL, 1),
(310653, 22787, 6600, '<td valign="top">Very pretty waterfall.  Much of the photo is dark side (for my tastes).</td>', 'Very pretty waterfall.  Much of the photo is dark side (for my tastes).', '2003-05-30 01:06:48.000000', NULL, 1),
(310654, 22781, 6600, '<td valign="top">Interesting color tone.... kind of pretty!  Nice detail and focus throughout the front portion of this photo (good choice of DOF).  Nicely done!</td>', 'Interesting color tone.... kind of pretty!  Nice detail and focus throughout the front portion of this photo (good choice of DOF).  Nicely done!', '2003-05-30 01:09:05.000000', NULL, 1),
(310656, 22734, 6600, '<td valign="top">Good color tone and composition, nice exposure.  Looking a bit sinister on purpose?</td>', 'Good color tone and composition, nice exposure.  Looking a bit sinister on purpose?', '2003-05-30 01:13:56.000000', NULL, 1),
(310712, 22751, 6999, '<td valign="top">This is a good shot - visually fascinating; but the first thing that strikes me is ''why isn''t it in colour?'' (and I don''t mean because it''s a duotone challenge).</td>', 'This is a good shot - visually fascinating; but the first thing that strikes me is ''why isn''t it in colour?'' (and I don''t mean because it''s a duotone challenge).', '2003-05-30 05:59:47.000000', NULL, 1),
(310725, 22632, 6349, '<td valign="top">i''ll give you a 10, if only for a beautiful new baby!</td>', 'i''ll give you a 10, if only for a beautiful new baby!', '2003-05-30 07:53:09.000000', NULL, 1),
(310731, 22683, 6349, '<td valign="top">wow. great shot.  love how the bottom splash is still and the top and side ones are still in motion.  black and white looks excellent.  interesting that the splash look slike a bottlecap, if you put it upside down and did some editing on the background it would make a cool absolut ad.  10</td>', 'wow. great shot.  love how the bottom splash is still and the top and side ones are still in motion.  black and white looks excellent.  interesting that the splash look slike a bottlecap, if you put it upside down and did some editing on the background it would make a cool absolut ad.  10', '2003-05-30 08:28:59.000000', NULL, 1),
(310732, 22284, 6349, '<td valign="top">Indeed.  Pure natural beauty.  You''re lucky to have such a great photogenic model.  Great photo.  10.</td>', 'Indeed.  Pure natural beauty.  You''re lucky to have such a great photogenic model.  Great photo.  10.', '2003-05-30 08:29:44.000000', NULL, 1),
(310733, 22787, 6349, '<td valign="top">I love the tones, the sofness, and the shutter speed to get the blurred water.  it feels like something from a dream or an illustration for a fairy tale.  Awesome shot.  good luck.  10</td>', 'I love the tones, the sofness, and the shutter speed to get the blurred water.  it feels like something from a dream or an illustration for a fairy tale.  Awesome shot.  good luck.  10', '2003-05-30 08:30:50.000000', NULL, 1),
(310734, 22637, 6349, '<td valign="top">Ok.  this is my favorite one.  It is perfect except for a little grain in the bottom left gray.  I''d suggest neatimage, but i can never get it to work right.  great job. 10</td>', 'Ok.  this is my favorite one.  It is perfect except for a little grain in the bottom left gray.  I''d suggest neatimage, but i can never get it to work right.  great job. 10', '2003-05-30 08:31:51.000000', NULL, 1),
(310735, 22463, 6349, '<td valign="top">lol.  this really made me smile.  the expressions are worth a million.  nice lighitng and choice of color, although it looks more natural on the dog.  great job.  10</td>', 'lol.  this really made me smile.  the expressions are worth a million.  nice lighitng and choice of color, although it looks more natural on the dog.  great job.  10', '2003-05-30 08:32:50.000000', NULL, 1),
(310738, 22510, 6349, '<td valign="top">oh, i will, i will.  great colors.  perfect shot for a postcard or brochure (as you know).  I would like to see this in full color because the golden snow throws me off a bit. Also, the feathered edges, and especially the visible line that looks blue on the left side and the one on the bottom right are pretty distracting. 9</td>', 'oh, i will, i will.  great colors.  perfect shot for a postcard or brochure (as you know).  I would like to see this in full color because the golden snow throws me off a bit. Also, the feathered edges, and especially the visible line that looks blue on the left side and the one on the bottom right are pretty distracting. 9', '2003-05-30 08:35:00.000000', NULL, 1),
(310740, 22785, 6349, '<td valign="top">I keep coming back to this.  it started at 8, then 9, now 10.  I think its my favorite one.  the blue is awseom and the focus and lighing are prefect.  I cant even imagine not giving it a 10 now.  How stupid of me.  This is awesome, i wish i could take pictures like this.  Remind me to buy a print one day when i move to a bigger house that i need to decorate! 10 10 10</td>', 'I keep coming back to this.  it started at 8, then 9, now 10.  I think its my favorite one.  the blue is awseom and the focus and lighing are prefect.  I cant even imagine not giving it a 10 now.  How stupid of me.  This is awesome, i wish i could take pictures like this.  Remind me to buy a print one day when i move to a bigger house that i need to decorate! 10 10 10', '2003-05-30 08:36:46.000000', NULL, 1),
(310741, 22505, 6349, '<td valign="top">and it was an excellent study.  Looks like you accomplished what you wanted to.  Great composition, form, tone, lighting, etc.  For some reason i would have liked all of the thumb to be lit, but im being very picky here.  I like the golden hue for the skin and the lines of the back and shoulderblades really position the body well in the frame.  It is soft and lovely, 9</td>', 'and it was an excellent study.  Looks like you accomplished what you wanted to.  Great composition, form, tone, lighting, etc.  For some reason i would have liked all of the thumb to be lit, but im being very picky here.  I like the golden hue for the skin and the lines of the back and shoulderblades really position the body well in the frame.  It is soft and lovely, 9', '2003-05-30 08:38:55.000000', NULL, 1),
(310743, 22752, 6349, '<td valign="top">Wooah, awesome.  Where do you come up with such models?  If only i could be so lucky.  I especially like the strands of hair coming down over the lips and the fact that the head is cut off.  I bet that will bother other people, but i think it gives it a nice modern look, or post post modern or contemporary or baroque or whatever people call it these days.  would be great in a body art magazine or billboard, etc.  The only thing i don''t like are the harsh highlights on the arms, especially the black one, although I realize that they are to give the skin a polished, oiled, bronzed look.  9</td>', 'Wooah, awesome.  Where do you come up with such models?  If only i could be so lucky.  I especially like the strands of hair coming down over the lips and the fact that the head is cut off.  I bet that will bother other people, but i think it gives it a nice modern look, or post post modern or contemporary or baroque or whatever people call it these days.  would be great in a body art magazine or billboard, etc.  The only thing i don''t like are the harsh highlights on the arms, especially the black one, although I realize that they are to give the skin a polished, oiled, bronzed look.  9', '2003-05-30 08:42:30.000000', NULL, 1),
(310745, 22214, 6349, '<td valign="top">I like this very much.  It seems timeless and mysterious and dark yet light.  Love the light coming in the back and leading toward you on the path.  The only thing that bothers me is that it is slightly too soft.  I like the tone of the softness but not the loss of clarity.  Also, what looks like garbage doesn''t fit the scene at all.  Great job. 9</td>', 'I like this very much.  It seems timeless and mysterious and dark yet light.  Love the light coming in the back and leading toward you on the path.  The only thing that bothers me is that it is slightly too soft.  I like the tone of the softness but not the loss of clarity.  Also, what looks like garbage doesn''t fit the scene at all.  Great job. 9', '2003-05-30 08:44:20.000000', NULL, 1),
(310746, 22274, 6349, '<td valign="top">oohh aaahh.  fantastic and interesting.  It''s a great illusion and wonderful black and white composition.  would have liked a littel more clarity.  Love the border.  9</td>', 'oohh aaahh.  fantastic and interesting.  It''s a great illusion and wonderful black and white composition.  would have liked a littel more clarity.  Love the border.  9', '2003-05-30 08:45:38.000000', NULL, 1),
(310754, 22754, 7628, '<td valign="top">Nice B&amp;W subject. I like the texture and tones of the mushroom stems.  i wish you could have gotten as nice an effect with the underside of the top ''shroom.  It isn''t quite in focus, and what light there is doesn''t do much.  The bright background shows how the ''shrooms are lurking in the shadows, but it is so bright and there is so much of it it is distracting. Also the bits of vine and other growing things around, while natural also detract from the focus. I''d be tempted to pull away these extra elements and find an angle that still emphasizes your subject (elder) while minimizes the background.  Use a larger DOF to have the edges of the ''shroom tops ion focus along with the stems.</td>', 'Nice B&W subject. I like the texture and tones of the mushroom stems.  i wish you could have gotten as nice an effect with the underside of the top ''shroom.  It isn''t quite in focus, and what light there is doesn''t do much.  The bright background shows how the ''shrooms are lurking in the shadows, but it is so bright and there is so much of it it is distracting. Also the bits of vine and other growing things around, while natural also detract from the focus. I''d be tempted to pull away these extra elements and find an angle that still emphasizes your subject (elder) while minimizes the background.  Use a larger DOF to have the edges of the ''shroom tops ion focus along with the stems.', '2003-05-30 09:31:54.000000', NULL, 1),
(310760, 22284, 7628, '<td valign="top">Not only is your model "beaute naturelle" your photo has captured her luminescent face very well.  I like the soft even lighting.  I''m not sure about the crop - the tilt of her eyes comes down neatly from the corner but I''d like to see more of her face.   The other corner is simply an out of focus shoulder (and strap) which doesn''t do anything for the picture (except distract).  Without the strap and the bit of upper arm, it would work better, but it would require redoing the shot at a slightly differesnt angle.  I think having her face against a dark background would be too harsh - not soft and natural - so you made a good choice of using her shoulder I think just needs a little modification. 7</td>', 'Not only is your model "beaute naturelle" your photo has captured her luminescent face very well.  I like the soft even lighting.  I''m not sure about the crop - the tilt of her eyes comes down neatly from the corner but I''d like to see more of her face.   The other corner is simply an out of focus shoulder (and strap) which doesn''t do anything for the picture (except distract).  Without the strap and the bit of upper arm, it would work better, but it would require redoing the shot at a slightly differesnt angle.  I think having her face against a dark background would be too harsh - not soft and natural - so you made a good choice of using her shoulder I think just needs a little modification. 7', '2003-05-30 09:42:27.000000', NULL, 1),
(310809, 22785, 9004, '<td valign="top">I love the choice of colour in this one. The white on that shade of blue is great.</td>', 'I love the choice of colour in this one. The white on that shade of blue is great.', '2003-05-30 11:10:32.000000', NULL, 1),
(310817, 22787, 2923, '<td valign="top">Sepia might look better, nice image. 8</td>', 'Sepia might look better, nice image. 8', '2003-05-30 11:24:24.000000', NULL, 1),
(310819, 22752, 7474, '<td valign="top"><br/></td>', '', '2003-05-30 11:29:04.000000', NULL, 1),
(310860, 22313, 6870, '<td valign="top">Well, I have to say first that I''m a sucker for reptiles and other herps, so you have a head start right there! However, I also really think that duotones bring out the texture of this lovely creature better than color could have, so it matches the challenge very well. Great lighting and composition really make this a winning photo in my book. I''m sure I''ll select it as a favorite when the challenge is over. Best of luck!</td>', 'Well, I have to say first that I''m a sucker for reptiles and other herps, so you have a head start right there! However, I also really think that duotones bring out the texture of this lovely creature better than color could have, so it matches the challenge very well. Great lighting and composition really make this a winning photo in my book. I''m sure I''ll select it as a favorite when the challenge is over. Best of luck!', '2003-05-30 12:41:12.000000', NULL, 1),
(310863, 22505, 6870, '<td valign="top">Very engaging lines and use of light celebrate and bring out the beauty of the human form. It''s refreshing that this is a child--very tastefully done.</td>', 'Very engaging lines and use of light celebrate and bring out the beauty of the human form. It''s refreshing that this is a child--very tastefully done.', '2003-05-30 12:43:52.000000', NULL, 1),
(310864, 22463, 6870, '<td valign="top">Wonderful stuff! Duotones capture the scultped lines of the expressions better than color would I feel, so this meets the challenge very well. Magnificent lighting and composition. Great photography. 10</td>', 'Wonderful stuff! Duotones capture the scultped lines of the expressions better than color would I feel, so this meets the challenge very well. Magnificent lighting and composition. Great photography. 10', '2003-05-30 12:45:16.000000', NULL, 1),
(310868, 22618, 6870, '<td valign="top">This works for me. Ich habe es gern! The utinsels are sharp, but the pot is just a bit fuzzy. Still, a wonderful, evocative image!</td>', 'This works for me. Ich habe es gern! The utinsels are sharp, but the pot is just a bit fuzzy. Still, a wonderful, evocative image!', '2003-05-30 12:46:46.000000', NULL, 1),
(310870, 22787, 6870, '<td valign="top">The tones here, created by excellent lighting, are marvelous!  The sharpness of the soil and plants contrast well with the fuzzy waterfall.</td>', 'The tones here, created by excellent lighting, are marvelous!  The sharpness of the soil and plants contrast well with the fuzzy waterfall.', '2003-05-30 12:48:19.000000', NULL, 1),
(310871, 22633, 6870, '<td valign="top">INcredible sky. I hope you didn''t paste that buliding into it. THe lighting and tones really work to make this a super shot.</td>', 'INcredible sky. I hope you didn''t paste that buliding into it. THe lighting and tones really work to make this a super shot.', '2003-05-30 12:49:36.000000', NULL, 1),
(310872, 22637, 6870, '<td valign="top">Wow. Stunning work. The light and contrasts in this photo are really marvelous. Composition is flawless. I just wish the feather were as sharp as its reflection. Still, wonderful image.</td>', 'Wow. Stunning work. The light and contrasts in this photo are really marvelous. Composition is flawless. I just wish the feather were as sharp as its reflection. Still, wonderful image.', '2003-05-30 12:51:11.000000', NULL, 1),
(310874, 22730, 6870, '<td valign="top">Tones here are appropriately gritty and dirty. Composition keeps my eye wandering arouind, but always ending up on that stairway. Nice work.</td>', 'Tones here are appropriately gritty and dirty. Composition keeps my eye wandering arouind, but always ending up on that stairway. Nice work.', '2003-05-30 12:52:19.000000', NULL, 1),
(310875, 22299, 6870, '<td valign="top">Superb composition! Lines and light keep my eye interested and engaged. I''d like to see it a little darker, but stunning image.</td>', 'Superb composition! Lines and light keep my eye interested and engaged. I''d like to see it a little darker, but stunning image.', '2003-05-30 12:53:35.000000', NULL, 1),
(310879, 22782, 6870, '<td valign="top">Very nice composition here. The roots form the base of the photo and do a good job at keeping this grounded--just like real roots! THey are ever so slightly out of focus, but the tones and contrasting lines of the trees do much to make up for that. Very nice work!</td>', 'Very nice composition here. The roots form the base of the photo and do a good job at keeping this grounded--just like real roots! THey are ever so slightly out of focus, but the tones and contrasting lines of the trees do much to make up for that. Very nice work!', '2003-05-30 12:55:26.000000', NULL, 1),
(310881, 22199, 6870, '<td valign="top">Your superb lighting really brings this flower to life!</td>', 'Your superb lighting really brings this flower to life!', '2003-05-30 12:56:11.000000', NULL, 1),
(310884, 22656, 2764, '<td valign="top">Do you need the building on the left?</td>', 'Do you need the building on the left?', '2003-05-30 12:57:43.000000', NULL, 1),
(310886, 22462, 6870, '<td valign="top">Endlessly engaging lines everywhere! My eye finally settles on that wooden thing in the upper middle. Great lighting and composition. As there is little focus here (which is good, I feel), it might be better to have everything in focus?</td>', 'Endlessly engaging lines everywhere! My eye finally settles on that wooden thing in the upper middle. Great lighting and composition. As there is little focus here (which is good, I feel), it might be better to have everything in focus?', '2003-05-30 12:58:02.000000', NULL, 1),
(310887, 22618, 2764, '<td valign="top">Wow, they look like people! 8</td>', 'Wow, they look like people! 8', '2003-05-30 13:01:13.000000', NULL, 1),
(310889, 22700, 2764, '<td valign="top">GREAT portrait!!!</td>', 'GREAT portrait!!!', '2003-05-30 13:07:28.000000', NULL, 1),
(310933, 22709, 2764, '<td valign="top">I think this is oddly cropped to place too much emphasis on the chin and neck.  The eyes are what is compelling and they need to be in a better place.  Also the negative space on the left and right are too balanced.  What about a tight crop on the right, leaving all the black on the left and then crop the bottom some. at least above the button.  8</td>', 'I think this is oddly cropped to place too much emphasis on the chin and neck.  The eyes are what is compelling and they need to be in a better place.  Also the negative space on the left and right are too balanced.  What about a tight crop on the right, leaving all the black on the left and then crop the bottom some. at least above the button.  8', '2003-05-30 15:01:07.000000', NULL, 1),
(310935, 22145, 2764, '<td valign="top">Lovely portrait -  What is the mold on the left?  her dress? 8</td>', 'Lovely portrait -  What is the mold on the left?  her dress? 8', '2003-05-30 15:12:43.000000', NULL, 1),
(310999, 22273, 3102, '<td valign="top">Awesome details -- you can almost count each individual pore!  Very impressive work, sure to be a contender this week. - 10</td>', 'Awesome details -- you can almost count each individual pore!  Very impressive work, sure to be a contender this week. - 10', '2003-05-30 17:20:22.000000', NULL, 1),
(311004, 22752, 3102, '<td valign="top">Is this the same woman who posed for "The Naked Chef" several weeks back?  Whatever the case, gotta like this!  My only beef is the somewhat harsh flash on the oily skin on the arms.  Or am I just upset that the arms are in the way?  :)</td>', 'Is this the same woman who posed for "The Naked Chef" several weeks back?  Whatever the case, gotta like this!  My only beef is the somewhat harsh flash on the oily skin on the arms.  Or am I just upset that the arms are in the way?  :)', '2003-05-30 17:24:03.000000', NULL, 1),
(311007, 22792, 3102, '<td valign="top">Very interesting!  I''d be really interested in seeing what this place looks like -- that''s quite a unique environment!  Well done. - 9</td>', 'Very interesting!  I''d be really interested in seeing what this place looks like -- that''s quite a unique environment!  Well done. - 9', '2003-05-30 17:24:55.000000', NULL, 1),
(311009, 22680, 3102, '<td valign="top">Excellent!  The details and depth of field are just awesome, not to mention that the toning seems to be perfect for the subject.  Well done.</td>', 'Excellent!  The details and depth of field are just awesome, not to mention that the toning seems to be perfect for the subject.  Well done.', '2003-05-30 17:25:41.000000', NULL, 1),
(311013, 22283, 3102, '<td valign="top">I''m afraid that the grain and the choice of toning just don''t work well for me.  Neither effect seems to do justice for the potential beauty of the subject matter.</td>', 'I''m afraid that the grain and the choice of toning just don''t work well for me.  Neither effect seems to do justice for the potential beauty of the subject matter.', '2003-05-30 17:27:01.000000', NULL, 1),
(311014, 22248, 3102, '<td valign="top">Looks more like a sneeze or something...?  I''m afraid this one just isn''t too appealing for my tastes... the expression and coloring are just a bit too overwhelming.</td>', 'Looks more like a sneeze or something...?  I''m afraid this one just isn''t too appealing for my tastes... the expression and coloring are just a bit too overwhelming.', '2003-05-30 17:28:47.000000', NULL, 1),
(311016, 22617, 3102, '<td valign="top">Great job capturing a moving subject like this in such perfect focus.  Looks like this could have easily been used in the sports section of the newspaper the next day.</td>', 'Great job capturing a moving subject like this in such perfect focus.  Looks like this could have easily been used in the sports section of the newspaper the next day.', '2003-05-30 17:30:01.000000', NULL, 1),
(311018, 22747, 3102, '<td valign="top">Looks like a photo straight out of one of my earliest albums from the 70s!  Interesting effect.</td>', 'Looks like a photo straight out of one of my earliest albums from the 70s!  Interesting effect.', '2003-05-30 17:31:16.000000', NULL, 1),
(311129, 22752, 7517, '<td valign="top">This is a great shot because it makes you wish you could see more.  Like the composition too.<br/></td>', 'This is a great shot because it makes you wish you could see more.  Like the composition too.', '2003-05-30 19:04:05.000000', NULL, 1),
(311139, 22792, 2700, '<td valign="top">um wow....</td>', 'um wow....', '2003-05-30 19:16:43.000000', NULL, 1),
(311158, 22698, 6900, '<td valign="top">Why did you cut the reflection off at the bottom?  The white is a bit overexposed and the composition leaves something to be desired (centered image, etc).  Nice contrast for duotones tho.</td>', 'Why did you cut the reflection off at the bottom?  The white is a bit overexposed and the composition leaves something to be desired (centered image, etc).  Nice contrast for duotones tho.', '2003-05-30 20:01:24.000000', NULL, 1),
(311166, 22371, 6597, '<td valign="top">good title</td>', 'good title', '2003-05-30 20:26:50.000000', NULL, 1),
(311180, 22699, 6025, '<td valign="top">v nice. Well seen, great tones, sharpness and dof. (9)</td>', 'v nice. Well seen, great tones, sharpness and dof. (9)', '2003-05-30 21:37:42.000000', NULL, 1),
(311195, 22510, 7711, '<td valign="top">nice capture, I like the tones you''ve chosen. Not high on the border, I think its a bit thick for the photo, but I love the old, hand done feel of this.</td>', 'nice capture, I like the tones you''ve chosen. Not high on the border, I think its a bit thick for the photo, but I love the old, hand done feel of this.', '2003-05-30 22:41:15.000000', NULL, 1),
(311197, 22635, 7711, '<td valign="top">I wouldn''t have chosen this sort of a glass for this picture because of the lines its creating with the straw. Also, I wish the whole image was a bit sharper, but fun effect.</td>', 'I wouldn''t have chosen this sort of a glass for this picture because of the lines its creating with the straw. Also, I wish the whole image was a bit sharper, but fun effect.', '2003-05-30 22:43:23.000000', NULL, 1),
(311198, 22117, 7711, '<td valign="top">I think your tilt is a little off on this, maybe a degree rotation to sort it out? :) Otherwise, great perspective and pattern.</td>', 'I think your tilt is a little off on this, maybe a degree rotation to sort it out? :) Otherwise, great perspective and pattern.', '2003-05-30 22:44:07.000000', NULL, 1),
