(311512, 22752, 6025, '<td valign="top">Very nice, but not at all sure about the reflection from the flash. The off-centreness is cool though, as is the bodypainting and the hair hanging across her face. Good work. (8)</td>', 'Very nice, but not at all sure about the reflection from the flash. The off-centreness is cool though, as is the bodypainting and the hair hanging across her face. Good work. (8)', '2003-05-31 14:19:37.000000', NULL, 1),
(311543, 22745, 7711, '<td valign="top">there are some neat items in this composition, but it lacks cohesion. We just aren''t sure what exactly is the meaning of the items we are looking at. The tones are nice though and the focus is crisp. :)</td>', 'there are some neat items in this composition, but it lacks cohesion. We just aren''t sure what exactly is the meaning of the items we are looking at. The tones are nice though and the focus is crisp. :)', '2003-05-31 15:48:55.000000', NULL, 1),
(311546, 22317, 7711, '<td valign="top">interesting shot. Seems to need just a tad more contrast or something though..the tones are all within a too small range.</td>', 'interesting shot. Seems to need just a tad more contrast or something though..the tones are all within a too small range.', '2003-05-31 15:52:04.000000', NULL, 1),
(311547, 22145, 7711, '<td valign="top">very nice emotion in this image. There is a bit of noise/graininess, but I don''t think it takes anything away from the composition. :)</td>', 'very nice emotion in this image. There is a bit of noise/graininess, but I don''t think it takes anything away from the composition. :)', '2003-05-31 15:52:54.000000', NULL, 1),
(311548, 22403, 7711, '<td valign="top">Hmm... I don''t think this subject is actually enhanced through a bw treatment. Its a beautiful waterfall and probably wants all its colour to really pop. That said, good composition and tones.</td>', 'Hmm... I don''t think this subject is actually enhanced through a bw treatment. Its a beautiful waterfall and probably wants all its colour to really pop. That said, good composition and tones.', '2003-05-31 15:53:48.000000', NULL, 1),
(311550, 22510, 6597, '<td valign="top">Looks like more than two colors  the challenge said two. But a real good photo</td>', 'Looks like more than two colors  the challenge said two. But a real good photo', '2003-05-31 16:13:07.000000', NULL, 1),
