(311669, 22747, 1031, '<td valign="top">Nice job "aging" this image.</td>', 'Nice job "aging" this image.', '2003-06-01 00:03:52.000000', NULL, 1),
(311675, 22743, 6600, '<td valign="top">Great capture, nice composition and contrast.  Would have been super to have the entire bird (gull) as sharp as the head appears to be (tough to do though).  Super job!</td>', 'Great capture, nice composition and contrast.  Would have been super to have the entire bird (gull) as sharp as the head appears to be (tough to do though).  Super job!', '2003-06-01 01:08:16.000000', NULL, 1),
(311677, 22777, 6600, '<td valign="top">I like the overall subject of this photo.  Good composition and balance.  To bad the fog or mist did not cloud the background out (the buildings beyond look a tad out of place in this shot).</td>', 'I like the overall subject of this photo.  Good composition and balance.  To bad the fog or mist did not cloud the background out (the buildings beyond look a tad out of place in this shot).', '2003-06-01 01:18:13.000000', NULL, 1),
