(311710, 22657, 3306, '<td valign="top">Really nice pattern. Excellent lighting. B &amp; W is perfect for this picture.</td>', 'Really nice pattern. Excellent lighting. B & W is perfect for this picture.', '2003-06-01 06:38:01.000000', NULL, 1),
