(311713, 22726, 3306, '<td valign="top">Very nice picture and pretty model but somehow it seems overly setup. I think a child would have been more suited to the subject of holding up a shell and listening to the ocean. Also I am not sure if it satisfies the duotones them as it just seems to be a softened color picture.</td>', 'Very nice picture and pretty model but somehow it seems overly setup. I think a child would have been more suited to the subject of holding up a shell and listening to the ocean. Also I am not sure if it satisfies the duotones them as it just seems to be a softened color picture.', '2003-06-01 06:43:37.000000', NULL, 1),
(311714, 22637, 3306, '<td valign="top">Great contrast. Excellent setup. Definitely satisfies the theme. Good Job.</td>', 'Great contrast. Excellent setup. Definitely satisfies the theme. Good Job.', '2003-06-01 06:44:50.000000', NULL, 1),
(311715, 22284, 4517, '<td valign="top">great detail and lighting. Border a bit uneven. 9</td>', 'great detail and lighting. Border a bit uneven. 9', '2003-06-01 06:48:58.000000', NULL, 1),
(311716, 22500, 3306, '<td valign="top">very nice portrait. I like the softness of the picture and the very intelligent look on the cats face.</td>', 'very nice portrait. I like the softness of the picture and the very intelligent look on the cats face.', '2003-06-01 06:50:34.000000', NULL, 1),
(311717, 22729, 3306, '<td valign="top">In color this picture would not have been that special. Black and white makes it exceptional. Good job.</td>', 'In color this picture would not have been that special. Black and white makes it exceptional. Good job.', '2003-06-01 06:52:15.000000', NULL, 1),
(311718, 22786, 4517, '<td valign="top">Perfect light and colour. 10</td>', 'Perfect light and colour. 10', '2003-06-01 06:52:43.000000', NULL, 1),
(311721, 22767, 3579, '<td valign="top">I like the delineation from white to grey. The shot looks a little over-processed though.</td>', 'I like the delineation from white to grey. The shot looks a little over-processed though.', '2003-06-01 07:32:13.000000', NULL, 1),
(311723, 22194, 3579, '<td valign="top">Lovely composition and contrast.</td>', 'Lovely composition and contrast.', '2003-06-01 07:35:48.000000', NULL, 1),
(311724, 22780, 3579, '<td valign="top">Great shot. You could sell it!</td>', 'Great shot. You could sell it!', '2003-06-01 07:51:30.000000', NULL, 1),
(311725, 22313, 3579, '<td valign="top">Great exposure on the shot. I would have loved to see his nose in more focus, and some more of his claws though.</td>', 'Great exposure on the shot. I would have loved to see his nose in more focus, and some more of his claws though.', '2003-06-01 07:53:50.000000', NULL, 1),
(311726, 22665, 3579, '<td valign="top">I think the forms of the chairs would have enabled you to crop even more tightly on the shop itself.</td>', 'I think the forms of the chairs would have enabled you to crop even more tightly on the shop itself.', '2003-06-01 07:54:53.000000', NULL, 1),
(311733, 22787, 3579, '<td valign="top">Fantastic shot! Great tonal range. 10</td>', 'Fantastic shot! Great tonal range. 10', '2003-06-01 08:14:35.000000', NULL, 1),
(311735, 22450, 3579, '<td valign="top">The tones look a little flat in this shot.</td>', 'The tones look a little flat in this shot.', '2003-06-01 08:24:51.000000', NULL, 1),
(311736, 22308, 3579, '<td valign="top">Lovely portrait. It could have been a bit sharper on her eyes though. Excellent composition lighting.  8.</td>', 'Lovely portrait. It could have been a bit sharper on her eyes though. Excellent composition lighting.  8.', '2003-06-01 08:26:49.000000', NULL, 1),
(311737, 22759, 3579, '<td valign="top">Lovely contrast.</td>', 'Lovely contrast.', '2003-06-01 08:28:18.000000', NULL, 1),
