(312201, 22479, 7711, '<td valign="top">Wow. Very nicely captured whites. :) Well done..white is so hard to get without blowing out, but you have managed it here. great!</td>', 'Wow. Very nicely captured whites. :) Well done..white is so hard to get without blowing out, but you have managed it here. great!', '2003-06-02 00:07:48.000000', NULL, 1),
(312202, 22620, 326, '<td valign="top">Wonderful wonderful shot! Just perfect!</td>', 'Wonderful wonderful shot! Just perfect!', '2003-06-02 00:07:48.000000', NULL, 1),
